# derive all D4 coordinate images, requiring reflection operations only where their symmetry region is established (2..29)
def orbit(r,c):
    seen={(r,c)}; todo=[(r,c)]
    while todo:
        a,b=todo.pop()
        nxt=[(b,a)]
        if 2<=a<=29: nxt.append((31-a,b))
        if 2<=b<=29: nxt.append((a,31-b))
        for x in nxt:
            if x not in seen and 0<=x[0]<30 and 0<=x[1]<30:
                seen.add(x); todo.append(x)
    return seen
